{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, a dimethoxybenzoquinolizine tertiary amine, had a mean oral systemic availability of only 0.049 ± 0.032 in patients, demonstrating very low F for a dimethoxyaryl/amine scaffold with extensive first-pass metabolism; despite the query's amide-for-ketone change, this supports a low-F outcome.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, which combines a dimethoxy-tetrahydroisoquinoline, an amide, and a basic amine, had an absolute oral bioavailability of 11.2% in healthy subjects, indicating that this amide/amine/dimethoxyaryl combination is prone to low systemic exposure; this is a close functional match to the query's amide plus basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Donepezil, a dimethoxyindanone with a basic piperidine and no hydrogen-bond donors, has an oral bioavailability of about 100% in humans, showing that dimethoxyaryl/basic-amine CNS drugs can be highly bioavailable; however, the query's higher molecular weight, amide group, and lower logD reduce transferability of this high-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a dimethoxybenzoquinolizine prodrug, has an absolute oral bioavailability of approximately 49% in humans, but its high F is largely attributable to prodrug ester design, which is not present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, flexible, basic amide with two dimethoxyaryl groups and no HBD. The most transferable human F data come from tetrabenazine (very low F) and almorexant (11% F), both sharing dimethoxyaryl/amine/amide features and demonstrating extensive first-pass or poor systemic exposure. High-F analogs such as donepezil and valbenazine are less structurally relevant or depend on prodrug/ketone features absent in the query. The physicochemical prior is mixed, but the low neutral fraction and moderate TPSA do not overcome the low-F experimental analogy. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Morgan similarities to all evidence compounds are low (<0.38), limiting transferability.",
    "No permeability or metabolic stability data are available for the query.",
    "The query's lactam/amide versus ketone or prodrug differences create uncertainty in extrapolating first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

